//! Bounded SMF 0/1 reader matching the public TTV score contract.
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::{BTreeMap,HashMap,HashSet};
use unicode_normalization::{UnicodeNormalization,char::is_combining_mark};

#[derive(Debug,Clone,Serialize,Deserialize)]pub struct ScoreError{pub message:String,pub code:String,pub tracks:Vec<Value>}
impl ScoreError{fn new(message:impl Into<String>)->Self{Self{message:message.into(),code:"invalid_midi".into(),tracks:Vec::new()}}}
type Result<T>=std::result::Result<T,ScoreError>;
#[derive(Debug,Clone)]struct Note{start:u64,end:u64,pitch:u8,velocity:u8}
#[derive(Debug,Clone)]struct Track{index:usize,name:String,notes:Vec<Note>,tempos:Vec<(u64,u32)>,lyrics:BTreeMap<u64,String>,end:u64}
impl Track{fn monophonic(&self)->bool{!self.notes.is_empty()&&self.notes.windows(2).all(|n|n[0].end<=n[1].start)}}
struct Reader<'a>{data:&'a[u8],position:usize}
impl<'a> Reader<'a>{fn new(data:&'a[u8])->Self{Self{data,position:0}}fn remaining(&self)->usize{self.data.len()-self.position}fn take(&mut self,n:usize)->Result<&'a[u8]>{if n>self.remaining(){return Err(ScoreError::new("O arquivo MIDI está truncado."));}let start=self.position;self.position+=n;Ok(&self.data[start..self.position])}fn byte(&mut self)->Result<u8>{Ok(self.take(1)?[0])}fn vlq(&mut self)->Result<u32>{let mut value=0;for _ in 0..4{let b=self.byte()?;value=(value<<7)|(b&127)as u32;if b&128==0{return Ok(value);}}Err(ScoreError::new("O MIDI contém um número VLQ inválido."))}fn be32(&mut self)->Result<usize>{Ok(u32::from_be_bytes(self.take(4)?.try_into().unwrap())as usize)}}
fn text_metadata(bytes:&[u8],lyric:bool)->Result<String>{
 let decoded=match std::str::from_utf8(bytes){Ok(s)=>s.to_owned(),Err(_)=>{if bytes.iter().any(|b|matches!(b,0x81|0x8d|0x8f|0x90|0x9d)){return Err(ScoreError::new("O MIDI contém texto com codificação inválida."));}encoding_rs::WINDOWS_1252.decode(bytes).0.into_owned()}};
 let category=regex::Regex::new(r"\p{C}").unwrap();let normalized:String=decoded.nfc().filter(|c|c.is_whitespace()||!category.is_match(&c.to_string())).map(|c|if c.is_whitespace(){' '}else{c}).collect();let mut text=normalized.split_whitespace().collect::<Vec<_>>().join(" ");if lyric{text=text.trim_start_matches(['/', '\\']).trim().to_owned();}if text.chars().count()>128{return Err(ScoreError::new(format!("{} MIDI ultrapassa 128 caracteres.",if lyric{"Uma sílaba da letra"}else{"O nome de uma faixa"})));}Ok(text)
}
fn read_track(data:&[u8],index:usize,counter:&mut usize)->Result<Track>{
 let mut r=Reader::new(data);let(mut tick,mut running,mut ended)=(0u64,None,false);let mut track=Track{index,name:String::new(),notes:Vec::new(),tempos:Vec::new(),lyrics:BTreeMap::new(),end:0};let mut active=HashMap::<(u8,u8),(u64,u8)>::new();
 while r.remaining()>0{*counter+=1;if *counter>50_000{return Err(ScoreError::new("O MIDI ultrapassa o limite de 50.000 eventos."));}tick+=r.vlq()?as u64;let first=r.byte()?;let(status,initial)=if first<128{(running.ok_or_else(||ScoreError::new("O MIDI usa running status sem um evento de canal anterior."))?,Some(first))}else{(first,None)};
  if(0x80..=0xef).contains(&status){running=Some(status);let kind=status&0xf0;let channel=status&15;let count=if kind==0xc0||kind==0xd0{1}else{2};let mut values=Vec::new();if let Some(first)=initial{values.push(first);}values.extend_from_slice(r.take(count-values.len())?);if values.iter().any(|b|*b>=128){return Err(ScoreError::new("O MIDI contém dados inválidos em um evento de canal."));}if kind!=0x80&&kind!=0x90{continue;}let(pitch,velocity)=(values[0],values[1]);let key=(channel,pitch);if kind==0x90&&velocity>0{if active.insert(key,(tick,velocity)).is_some(){return Err(ScoreError::new("O MIDI repete uma nota antes de encerrá-la."));}}else{let(start,velocity)=active.remove(&key).ok_or_else(||ScoreError::new("O MIDI encerra uma nota que não foi iniciada."))?;if tick<=start{return Err(ScoreError::new("O MIDI contém uma nota sem duração positiva."));}if channel!=9{track.notes.push(Note{start,end:tick,pitch,velocity});}}continue;}
  running=None;
  match status{0xff=>{let meta=r.byte()?;if meta>=128{return Err(ScoreError::new("O MIDI contém um tipo de metadado inválido."));}let len=r.vlq()?as usize;let payload=r.take(len)?;match meta{0x2f=>{if !payload.is_empty()||r.remaining()>0{return Err(ScoreError::new("O evento de fim da faixa MIDI é inválido."));}ended=true;break;},0x51=>{if payload.len()!=3||payload.iter().all(|b|*b==0){return Err(ScoreError::new("O MIDI contém um andamento inválido."));}track.tempos.push((tick,((payload[0]as u32)<<16)|((payload[1]as u32)<<8)|payload[2]as u32));},3=>track.name=text_metadata(payload,false)?,5=>{let value=text_metadata(payload,true)?;if !value.is_empty()&&track.lyrics.insert(tick,value).is_some(){return Err(ScoreError::new("O MIDI contém mais de uma letra na mesma posição."));}},_=>()}},0xf0|0xf7=>{let len=r.vlq()?as usize;r.take(len)?;},_=>return Err(ScoreError::new("O MIDI contém um evento de sistema não suportado."))}
 }
 if !ended{return Err(ScoreError::new("Uma faixa MIDI não possui o evento de fim da faixa."));}if !active.is_empty(){return Err(ScoreError::new("O MIDI contém notas iniciadas sem encerramento."));}track.notes.sort_by_key(|n|(n.start,n.end,n.pitch));track.end=tick;Ok(track)
}
struct Timeline{division:u16,ticks:Vec<u64>,numerators:Vec<u128>,tempos:Vec<u32>}
impl Timeline{fn new(tracks:&[Track],division:u16)->Self{let mut out=Self{division,ticks:vec![0],numerators:vec![0],tempos:vec![500_000]};if let Some(track)=tracks.iter().find(|t|!t.tempos.is_empty()){let changes:BTreeMap<_,_>=track.tempos.iter().copied().collect();for(tick,tempo)in changes{let i=out.ticks.len()-1;if tick==out.ticks[i]{out.tempos[i]=tempo;}else{out.numerators.push(out.numerators[i]+(tick-out.ticks[i])as u128*out.tempos[i]as u128);out.ticks.push(tick);out.tempos.push(tempo);}}}out}fn numerator(&self,tick:u64)->u128{let i=self.ticks.partition_point(|t|*t<=tick)-1;self.numerators[i]+(tick-self.ticks[i])as u128*self.tempos[i]as u128}fn milliseconds(&self,tick:u64)->u64{let denominator=self.division as u128*1000;((self.numerator(tick)+denominator/2)/denominator)as u64}}
fn read_midi(data:&[u8])->Result<(Vec<Track>,Timeline)>{
 if data.len()>512*1024{return Err(ScoreError::new("O arquivo MIDI ultrapassa o limite de 512 KiB."));}let mut r=Reader::new(data);if r.take(4)?!=b"MThd"{return Err(ScoreError::new("O anexo não é um arquivo MIDI padrão (SMF)."));}let size=r.be32()?;if size<6{return Err(ScoreError::new("O cabeçalho MIDI está incompleto."));}let header=r.take(size)?;let format=u16::from_be_bytes([header[0],header[1]]);let count=u16::from_be_bytes([header[2],header[3]])as usize;let division=u16::from_be_bytes([header[4],header[5]]);if format>1{return Err(ScoreError::new("Use um MIDI do formato 0 ou 1; o formato 2 não é suportado."));}if !(1..=64).contains(&count)||format==0&&count!=1{return Err(ScoreError::new("O MIDI deve conter entre 1 e 64 faixas (uma no formato 0)."));}if division&0x8000!=0{return Err(ScoreError::new("MIDI com divisão SMPTE não é suportado; exporte em PPQ."));}if division==0{return Err(ScoreError::new("A resolução PPQ do MIDI deve ser maior que zero."));}let mut tracks=Vec::new();let mut counter=0;for i in 0..count{if r.take(4)?!=b"MTrk"{return Err(ScoreError::new("Uma faixa MIDI não possui o marcador MTrk."));}let size=r.be32()?;tracks.push(read_track(r.take(size)?,i,&mut counter)?);}if r.remaining()>0{return Err(ScoreError::new("O MIDI contém dados extras depois das faixas declaradas."));}let timeline=Timeline::new(&tracks,division);Ok((tracks,timeline))
}
fn named(track:&Track)->bool{let folded=track.name.to_lowercase().nfkc().collect::<String>();let normalized:String=folded.nfkd().filter(|c|!is_combining_mark(*c)).collect();regex::Regex::new(r"\b(?:vocals?|voices?|melody|melodia|lead|voz|canto|singing|vocaloid)\b").unwrap().is_match(&normalized)||folded.contains("ボーカル")||folded.contains("メロディ")}
fn lyric_matches(track:&Track,source:&Track)->usize{let onsets:HashSet<_>=track.notes.iter().map(|n|n.start).collect();source.lyrics.keys().filter(|t|onsets.contains(t)).count()}
fn lyric_sources<'a>(track:&Track,tracks:&'a[Track])->Vec<&'a Track>{let onsets:HashSet<_>=track.notes.iter().map(|n|n.start).collect();tracks.iter().filter(|t|t.notes.is_empty()&&!t.lyrics.is_empty()&&t.lyrics.keys().all(|k|onsets.contains(k))).collect()}
fn details(track:&Track,tracks:&[Track],timeline:&Timeline)->Value{let matches=lyric_sources(track,tracks).iter().map(|t|t.lyrics.len()).chain(std::iter::once(lyric_matches(track,track))).max().unwrap_or(0);json!({"index":track.index,"name":track.name,"note_count":track.notes.len(),"monophonic":track.monophonic(),"duration_ms":timeline.milliseconds(track.end),"lyric_matches":matches})}
fn choose<'a>(tracks:&'a[Track],timeline:&Timeline,index:Option<usize>)->Result<&'a Track>{
 if let Some(index)=index{let track=tracks.get(index).ok_or_else(||ScoreError::new("O índice da faixa MIDI é inválido; os índices começam em 0."))?;if track.notes.is_empty(){return Err(ScoreError::new(format!("A faixa {index} não contém notas melódicas; a percussão é ignorada.")));}if !track.monophonic(){return Err(ScoreError::new(format!("A faixa {index} tem notas sobrepostas. Exporte a melodia monofônica separada.")));}return Ok(track);}
 let candidates:Vec<_>=tracks.iter().filter(|t|t.monophonic()).collect();let direct:Vec<_>=candidates.iter().copied().filter(|t|lyric_matches(t,t)>0).collect();if direct.len()==1{return Ok(direct[0]);}if direct.is_empty(){let external:Vec<_>=candidates.iter().copied().filter(|t|!lyric_sources(t,tracks).is_empty()).collect();if external.len()==1{return Ok(external[0]);}}
 let named:Vec<_>=if direct.is_empty(){&candidates}else{&direct}.iter().copied().filter(|t|named(t)).collect();if named.len()==1{return Ok(named[0]);}let polyphony:Vec<_>=tracks.iter().filter(|t|!t.notes.is_empty()&&!t.monophonic()&&(self::named(t)||lyric_matches(t,t)>0)).collect();if !polyphony.is_empty()&&direct.is_empty()&&named.is_empty(){let labels=polyphony.iter().map(|t|t.index.to_string()).collect::<Vec<_>>().join(", ");return Err(ScoreError::new(format!("A melodia nas faixas {labels} tem notas sobrepostas. Exporte a melodia monofônica separada.")));}if candidates.len()==1{return Ok(candidates[0]);}if candidates.is_empty(){return Err(ScoreError::new("O MIDI não possui uma faixa melódica monofônica; exporte a melodia separada."));}let labels=candidates.iter().map(|t|format!("{}: {} ({} notas)",t.index,if t.name.is_empty(){"sem nome"}else{&t.name},t.notes.len())).collect::<Vec<_>>().join("; ");Err(ScoreError{message:format!("O MIDI tem mais de uma melodia possível: {labels}. Escolha uma faixa pelo índice ou exporte só a melodia."),code:"ambiguous_track".into(),tracks:candidates.iter().map(|t|details(t,tracks,timeline)).collect()})
}
pub fn inspect_midi_tracks(data:&[u8])->Result<Vec<Value>>{let(tracks,timeline)=read_midi(data)?;let recommended=choose(&tracks,&timeline,None).ok().map(|t|t.index);Ok(tracks.iter().map(|t|{let mut d=details(t,&tracks,&timeline);d["recommended"]=json!(recommended==Some(t.index));d}).collect())}
pub fn parse_midi(data:&[u8],lyrics:&str,index:Option<usize>)->Result<Value>{
 let(tracks,timeline)=read_midi(data)?;let selected=choose(&tracks,&timeline,index)?;if selected.notes.len()>128{return Err(ScoreError::new("A melodia ultrapassa o limite de 128 notas."));}let denominator=timeline.division as u128*1000;if timeline.numerator(selected.end)>60_000*denominator{return Err(ScoreError::new("A melodia ultrapassa o limite de 60 segundos, incluindo as pausas."));}
 let message=!lyrics.trim().is_empty();let mut source=None;if !message{if !selected.lyrics.is_empty(){source=Some(selected);}else{let external=lyric_sources(selected,&tracks);if !external.is_empty(){if external.iter().skip(1).any(|t|t.lyrics!=external[0].lyrics){return Err(ScoreError::new("O MIDI contém letras diferentes para a mesma melodia; envie a letra na mensagem."));}source=Some(external[0]);}else if tracks.iter().any(|t|t.notes.is_empty()&&!t.lyrics.is_empty()){return Err(ScoreError::new("A letra MIDI não coincide com o início das notas; envie a letra na mensagem ou ajuste o arquivo."));}}if source.is_some_and(|s|s.lyrics.keys().any(|t|!selected.notes.iter().any(|n|n.start==*t))){return Err(ScoreError::new("A letra MIDI não coincide com o início das notas; envie a letra na mensagem ou ajuste o arquivo."));}}
 let mut notes=Vec::new();let mut seen=false;for n in &selected.notes{if !(36..=96).contains(&n.pitch){return Err(ScoreError::new("A melodia deve usar notas MIDI entre 36 e 96 (C2 a C7)."));}if timeline.numerator(n.end)-timeline.numerator(n.start)<40*denominator{return Err(ScoreError::new("Cada nota da melodia precisa durar pelo menos 40 ms."));}let start=timeline.milliseconds(n.start);let end=timeline.milliseconds(n.end);let mut note=json!({"midi_note":n.pitch,"start_ms":start,"duration_ms":end-start,"velocity":n.velocity});if !message{let lyric=source.and_then(|s|s.lyrics.get(&n.start));note["lyric"]=json!(lyric.map(String::as_str).unwrap_or(if seen{"~"}else{"a"}));seen|=lyric.is_some();}notes.push(note);}
 Ok(json!({"version":1,"track_index":selected.index,"duration_ms":timeline.milliseconds(selected.end),"lyrics_source":if message{"message"}else if source.is_some(){"midi"}else{"vowel"},"notes":notes}))
}

#[cfg(test)]mod tests{use super::*;#[test]fn rejects_large_and_truncated(){assert!(parse_midi(&vec![0;512*1024+1],"",None).unwrap_err().message.contains("512"));assert!(parse_midi(b"MThd","",None).unwrap_err().message.contains("truncado"));}#[test]fn production_score_contracts(){let cases:Value=serde_json::from_str(include_str!("../tests/fixtures/midi-contract.json")).unwrap();for case in cases.as_array().unwrap(){let data:Vec<u8>=serde_json::from_value(case["data"].clone()).unwrap();let result=parse_midi(&data,case["lyrics"].as_str().unwrap_or(""),case["track_index"].as_u64().map(|n|n as usize));let actual=match result{Ok(score)=>json!({"ok":true,"value":score}),Err(error)=>json!({"ok":false,"error":error})};assert_eq!(actual,case["parse"],"MIDI case {}",case["name"]);let actual=match inspect_midi_tracks(&data){Ok(value)=>json!({"ok":true,"value":value}),Err(error)=>json!({"ok":false,"error":error})};assert_eq!(actual,case["inspect"],"MIDI inspect {}",case["name"]);}}}
